<script>
export default {
  name: "TrainingRecommendationDetails",
  props: ["queries"],
  data() {
    return {
      loading: true,
      loadingResponses: false,
      error: false,
      errorMessage: "",

      // Recommendation ID from route
      recommendationId: null,

      // Main data
      recommendation: null,
      departmentResponses: [],
      expandedResponses: [],
    };
  },

  computed: {
    interestedCount() {
      return this.departmentResponses.filter(
        (r) => r.responseType === "interested",
      ).length;
    },

    totalNominations() {
      return this.departmentResponses.reduce(
        (sum, r) => sum + (r.participants ? r.participants.length : 0),
        0,
      );
    },
  },

  async mounted() {
    // Get recommendation ID from route query
    this.recommendationId = this.queries.recommendation;

    if (!this.recommendationId) {
      this.error = true;
      this.errorMessage = "No recommendation ID specified";
      this.loading = false;
      return;
    }

    await this.loadRecommendation();
    await this.loadDepartmentResponses();
  },

  methods: {
    async loadRecommendation() {
      try {
        this.loading = true;
        this.error = false;

        const response = await fetch(`/fhir/Basic/${this.recommendationId}`);

        if (!response.ok) {
          throw new Error("Training recommendation not found");
        }

        const resource = await response.json();

        // Parse recommendation
        this.recommendation = {
          id: resource.id,
          title:
            this.getExtensionValue(
              resource,
              "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
              "valueString",
            ) || "Untitled Training",

          institution: this.getExtensionValue(
            resource,
            "http://ihris.org/fhir/StructureDefinition/planning-institution",
            "valueString",
          ),

          qualificationLevel: this.getExtensionValue(
            resource,
            "http://ihris.org/fhir/StructureDefinition/qualification-level",
            "valueCoding",
          )?.display,

          qualification: (() => {
            const other = resource.extension?.find(
              (e) => e.url === "http://ihris.org/fhir/StructureDefinition/qualification-name-other",
            )?.valueString;
            const ref = resource.extension?.find(
              (e) => e.url === "http://ihris.org/fhir/StructureDefinition/qualification-name",
            )?.valueReference?.display;
            return other || ref || null;
          })(),

          country: this.getExtensionValue(
            resource,
            "http://ihris.org/fhir/StructureDefinition/country",
            "valueCoding",
          )?.display,

          description: this.getExtensionValue(
            resource,
            "http://ihris.org/fhir/StructureDefinition/description",
            "valueString",
          ),

          departments: [],

          startDate: this.getExtensionValue(
            resource,
            "http://ihris.org/fhir/StructureDefinition/start-date",
            "valueDate",
          ),

          endDate: this.getExtensionValue(
            resource,
            "http://ihris.org/fhir/StructureDefinition/end-date",
            "valueDate",
          ),

          location: this.getExtensionValue(
            resource,
            "http://ihris.org/fhir/StructureDefinition/training-location",
            "valueString",
          ),

          maxParticipants: this.getExtensionValue(
            resource,
            "http://ihris.org/fhir/StructureDefinition/total-participants",
            "valueInteger",
          ),

          methodology: this.getExtensionValue(
            resource,
            "http://ihris.org/fhir/StructureDefinition/learning-methodology",
            "valueCoding",
          )?.display,

          // Extract designation references
          designations: resource.extension
            .filter(
              (ext) =>
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/designation",
            )
            .map(
              (ext) =>
                ext.valueReference?.display || ext.valueReference?.reference,
            )
            .filter(Boolean),

          // Extract salary grade references
          salaryGrades: resource.extension
            .filter(
              (ext) =>
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/salary-grade",
            )
            .map(
              (ext) =>
                ext.valueReference?.display || ext.valueReference?.reference,
            )
            .filter(Boolean),

          // Extract age criteria
          ageCriteria: resource.extension
            .filter(
              (ext) =>
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/training-recommendation-age",
            )
            .map((ext) => {
              const ageExt = ext.extension || [];
              const typeExt = ageExt.find((e) => e.url === "condition");
              const valueExt = ageExt.find((e) => e.url === "exact");
              const minValueExt = ageExt.find((e) => e.url === "min");
              const maxValueExt = ageExt.find((e) => e.url === "max");

              if (typeExt) {
                const ageItem = {
                  type: typeExt.valueString,
                };

                if (valueExt) {
                  ageItem.value = valueExt.valueInteger;
                }
                if (minValueExt) {
                  ageItem.minValue = minValueExt.valueInteger;
                }
                if (maxValueExt) {
                  ageItem.maxValue = maxValueExt.valueInteger;
                }

                return ageItem;
              }
              return null;
            })
            .filter(Boolean),

          // Extract qualification criteria
          // Structure: extension[url=training-recommendation-qualification]
          //   → extension[url=qualification].valueCoding  +  extension[url=condition].valueString
          qualificationCriteria: resource.extension
            .filter(
              (ext) =>
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/training-recommendation-qualification",
            )
            .map((ext) => {
              const q = ext.extension || [];
              const lvl = q.find((e) => e.url === "qualification")?.valueCoding;
              const condition =
                q.find((e) => e.url === "condition")?.valueString || "atleast";
              if (!lvl?.code) return null;
              return {
                code: lvl.code,
                display: lvl.display || lvl.code,
                condition,
              };
            })
            .filter(Boolean),
        };
        if (this.recommendation.designations.length) {
          for (let index in this.recommendation.designations) {
            let designation = this.recommendation.designations[index];
            let desDet = await fetch("/fhir/" + designation);
            desDet = await desDet.json();
            let name = desDet.extension.find((ext) => {
              return (
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
              );
            })?.valueString;
            this.recommendation.designations[index] = name;
          }
        }
        if (this.recommendation.salaryGrades.length) {
          for (let index in this.recommendation.salaryGrades) {
            let grade = this.recommendation.salaryGrades[index];
            let gradeDet = await fetch("/fhir/" + grade);
            gradeDet = await gradeDet.json();
            let name = gradeDet.extension.find((ext) => {
              return (
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
              );
            })?.valueString;
            this.recommendation.salaryGrades[index] = name;
          }
        }

        let departments = resource.extension.filter((ext) => {
          return (
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/training-recommendation-department"
          );
        });
        for (let department of departments) {
          this.recommendation.departments.push({
            name: department.extension.find((ext) => {
              return ext.url === "department";
            })?.valueCoding?.display,
            participants: department.extension.find((ext) => {
              return ext.url === "total-participants";
            })?.valueInteger,
          });
        }

        this.loading = false;
      } catch (error) {
        console.error("Error loading recommendation:", error);
        this.error = true;
        this.errorMessage =
          error.message || "Failed to load training recommendation";
        this.loading = false;
      }
    },

    async loadDepartmentResponses() {
      try {
        this.loadingResponses = true;

        // Search for responses using trainingrecommendation parameter
        const response = await fetch(
          `/fhir/Basic?_profile=http://ihris.org/fhir/StructureDefinition/training-recommendation-response-profile&trainingrecommendation=Basic/${this.recommendationId}`,
        );

        if (!response.ok) {
          throw new Error("Failed to load department responses");
        }

        const results = await response.json();

        this.departmentResponses = [];

        if (results.entry && results.entry.length > 0) {
          for (const entry of results.entry) {
            const responseData = await this.parseResponse(entry.resource);
            this.departmentResponses.push(responseData);

            // Load HR reviews for this response
            this.loadHRReviews(responseData);
          }
        }

        this.loadingResponses = false;
      } catch (error) {
        console.error("Error loading department responses:", error);
        this.loadingResponses = false;
      }
    },

    async parseResponse(resource) {
      const responseData = {
        id: resource.id,
        resourceRef: `Basic/${resource.id}`,

        department:
          this.getExtensionValue(
            resource,
            "http://ihris.org/fhir/StructureDefinition/department",
            "valueCoding",
          )?.display || "Unknown",

        responseType: this.getExtensionValue(
          resource,
          "http://ihris.org/fhir/StructureDefinition/training-recommendation-response",
          "valueCoding",
        )?.code,

        responseDisplay:
          this.getExtensionValue(
            resource,
            "http://ihris.org/fhir/StructureDefinition/training-recommendation-response",
            "valueCoding",
          )?.display || "Unknown",

        status: this.getExtensionValue(
          resource,
          "http://ihris.org/fhir/StructureDefinition/request-status",
          "valueCoding",
        )?.code,

        statusDisplay:
          this.getExtensionValue(
            resource,
            "http://ihris.org/fhir/StructureDefinition/request-status",
            "valueCoding",
          )?.display || "Unknown",

        submissionDate: this.getExtensionValue(
          resource,
          "http://ihris.org/fhir/StructureDefinition/event-date",
          "valueDate",
        ),

        hodComments: this.getExtensionValue(
          resource,
          "http://ihris.org/fhir/StructureDefinition/comments",
          "valueString",
        ),

        practitionerRefs: resource.extension
          .filter(
            (ext) =>
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference",
          )
          .map((ext) => ext.valueReference.reference),

        participants: [],
        hrReviews: [],
        loadingReviews: true,
      };

      // Load participants
      if (responseData.practitionerRefs.length > 0) {
        responseData.participants = await this.loadParticipants(
          responseData.practitionerRefs,
        );
      } else {
        responseData.participants = [];
      }

      return responseData;
    },

    async loadParticipants(practitionerRefs) {
      const participants = [];

      for (const practitionerId of practitionerRefs) {
        try {
          const response = await fetch(
            `/fhir/PractitionerRole?practitioner=${practitionerId}&_include=PractitionerRole:practitioner&_include=PractitionerRole:roleposition`,
          );

          if (!response.ok) {
            console.error(`Failed to load practitioner ${practitionerId}`);
            continue;
          }

          const data = await response.json();

          const practitioner = data.entry?.find(
            (e) => e.resource.resourceType === "Practitioner",
          )?.resource;

          if (!practitioner) continue;

          const position = data.entry?.find(
            (e) => e.resource.resourceType === "Basic",
          )?.resource;

          const name = practitioner.name?.[0];
          let fullName = "";

          if (name) {
            if (name.given?.length) {
              fullName = name.given.join(" ");
            }
            if (name.family) {
              fullName += " " + name.family;
            }
          }
          let age = null;
          if (practitioner.birthDate) {
            const birthDate = new Date(practitioner.birthDate);
            const today = new Date();
            age = today.getFullYear() - birthDate.getFullYear();
            const monthDiff = today.getMonth() - birthDate.getMonth();
            if (
              monthDiff < 0 ||
              (monthDiff === 0 && today.getDate() < birthDate.getDate())
            ) {
              age--;
            }
          }
          let grade = position?.extension?.find((ext) => {
            return (
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/salary-grade"
            );
          })?.valueReference?.reference;
          if (grade) {
            grade = await fetch("/fhir/" + grade);
            grade = await grade.json();
          }
          const jobTitle = position?.extension?.find(
            (ext) =>
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
          )?.valueString;

          participants.push({
            id: practitionerId,
            name: fullName.trim() || "Unknown",
            jobTitle: jobTitle || "Not specified",
            age,
            grade: grade?.extension?.find((ext) => {
              return (
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
              );
            })?.valueString,
          });
        } catch (error) {
          console.error(`Error loading participant ${practitionerId}:`, error);
        }
      }

      return participants;
    },

    async loadHRReviews(responseData) {
      try {
        // Search for HR reviews using trainingrecommendationresponse parameter
        const response = await fetch(
          `/fhir/Basic?_profile=http://ihris.org/fhir/StructureDefinition/hr-training-recommendation-review-profile&trainingrecommendationresponse=Basic/${responseData.id}`,
        );

        if (!response.ok) {
          responseData.loadingReviews = false;
          return;
        }

        const results = await response.json();
        responseData.hrReviews = [];

        if (results.entry && results.entry.length > 0) {
          for (const entry of results.entry) {
            let user = entry.resource.extension.find((ext) => {
              return (
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/user-reference"
              );
            })?.valueReference?.reference;
            user = await fetch("/fhir/Person/" + user.split("/")[1]);
            user = await user.json();
            const review = {
              id: entry.resource.id,

              decision: entry.resource.extension.find((ext) => {
                return (
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/review-status"
                );
              })?.valueCoding.code,

              comments: this.getExtensionValue(
                entry.resource,
                "http://ihris.org/fhir/StructureDefinition/comments",
                "valueString",
              ),

              reviewDate: this.getExtensionValue(
                entry.resource,
                "http://ihris.org/fhir/StructureDefinition/event-date",
                "valueDate",
              ),

              reviewerRef: this.getExtensionValue(
                entry.resource,
                "http://ihris.org/fhir/StructureDefinition/user-reference",
                "valueReference",
              )?.reference,

              reviewerName: user?.name?.[0]?.text,
            };

            responseData.hrReviews.push(review);
          }
        }

        responseData.loadingReviews = false;
      } catch (error) {
        console.error("Error loading HR reviews:", error);
        responseData.loadingReviews = false;
      }
    },

    getExtensionValue(resource, url, type) {
      const extension = resource.extension?.find((ext) => ext.url === url);
      return extension ? extension[type] : null;
    },

    formatDate(dateString) {
      if (!dateString) return "Not specified";
      const date = new Date(dateString);
      return date.toLocaleDateString("en-US", {
        year: "numeric",
        month: "long",
        day: "numeric",
      });
    },

    formatAgeCriteria(ageItem) {
      if (!ageItem || !ageItem.type) return "";

      switch (ageItem.type) {
        case "greater-than":
          return `Age > ${ageItem.minValue}`;
        case "less-than":
          return `Age < ${ageItem.maxValue}`;
        case "range":
          return `Age ${ageItem.minValue}-${ageItem.maxValue}`;
        case "exact":
          return `Age = ${ageItem.value}`;
        default:
          return "";
      }
    },

    getResponseColor(responseType) {
      switch (responseType) {
        case "interested":
          return "green";
        case "not-interested":
          return "red";
        default:
          return "grey";
      }
    },

    getResponseIcon(responseType) {
      switch (responseType) {
        case "interested":
          return "mdi-hand-okay";
        case "not-interested":
          return "mdi-hand-back-left";
        default:
          return "mdi-help-circle";
      }
    },

    getStatusColor(status) {
      const colors = {
        submitted: "blue",
        undersupervisorreview: "orange",
        underhodreview: "orange",
        underhrreview: "orange",
        underpsreview: "orange",
        approved: "green",
        rejected: "red",
      };
      return colors[status] || "grey";
    },

    getResponseStatusColor() {
      if (this.departmentResponses.length === 0) return "grey";
      if (this.interestedCount > 0) return "green";
      return "orange";
    },

    getReviewCardClass(decision) {
      if (decision === "approved") return "green lighten-5";
      if (decision === "rejected") return "red lighten-5";
      return "";
    },

    goBack() {
      this.$router.go(-1);
    },
  },
};
</script>

